/**
 * VC-DRV-25 / 26 / 27 against expected_results.json (generated by generate_drv_reference.py from drv_reference.json): each reference quantity is MEASURED here
 * by a route independent of the closed form where one exists (bisection of the envelope, numerical maximum of the torque-speed curve, a ringing run, a loaded static run),
 * and held to the tolerance of its case.
 */
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { setPhysicsEngine } from '@core/dynamics/physicsEngine';
import type { InductionMotor, PmsmMotor } from '@core/model/drives';
import { createMujocoPhysics } from '@physics-mujoco/mujocoPhysics';
import { inductionParameters, inductionPoint, synchronousSpeed } from '@dynamics/sim/actuators/induction';
import { pmsmEnvelope, pmsmParameters } from '@dynamics/sim/actuators/pmsm';
import { expectedResults, seriesOf, simulate } from './fixtures';
import { INDUCTION_SHEET, MACHINE_SOURCE, PMSM_SHEET, STEPPER_SHEET, machineBench } from './machineFixtures';

beforeAll(async () => setPhysicsEngine(await createMujocoPhysics()));
afterAll(() => setPhysicsEngine(null));

const cases = (id: string): { quantity: string; value: number; tolerance: { rel: number } }[] =>
  expectedResults.cases.filter((entry) => entry.id === id) as unknown as { quantity: string; value: number; tolerance: { rel: number } }[];
const caseOf = (id: string, text: string): { value: number; tolerance: { rel: number } } => {
  const found = cases(id).find((entry) => entry.quantity.includes(text));
  if (found === undefined) throw new Error(`${id}: no case '${text}'`);
  return found;
};
const within = (measured: number, reference: { value: number; tolerance: { rel: number } }): void => {
  expect(Math.abs(measured / reference.value - 1)).toBeLessThanOrEqual(reference.tolerance.rel);
};

/** Largest x in [low, high] where `holds(x)` (monotone: true then false), by bisection. */
function bisect(holds: (x: number) => boolean, low: number, high: number): number {
  let [a, b] = [low, high];
  for (let k = 0; k < 80; k++) {
    const mid = (a + b) / 2;
    if (holds(mid)) a = mid;
    else b = mid;
  }
  return a;
}

describe('VC-DRV-25: PMSM (lambda 0.01 Wb, p 4, L 0.2 mH, 20 A, 24 V)', () => {
  const motor: PmsmMotor = { id: 'm', kind: 'pmsm', joint: 'j', datasheet: PMSM_SHEET, source: MACHINE_SOURCE as PmsmMotor['source'] };
  const p = pmsmParameters(motor);
  const limits = { currentA: 20, busVoltageV: 24 };
  const torque = (w: number): number => pmsmEnvelope(p, limits, w).torqueNm;

  it('maximum torque 1.5 p lambda I (1e-6)', () => within(torque(0), caseOf('VC-DRV-25', 'maximum torque')));

  it('base speed: the largest speed with the full torque, found by bisection (0.5 %)', () => {
    within(
      bisect((w) => torque(w) >= torque(0) * (1 - 1e-12), 1, 5000),
      caseOf('VC-DRV-25', 'base speed'),
    );
  });

  it('maximum speed: the largest speed with a positive torque, found by bisection (0.5 %)', () => {
    within(
      bisect((w) => torque(w) > 0, 400, 5000),
      caseOf('VC-DRV-25', 'maximum speed'),
    );
  });

  it('envelope torque at 100 / 300 / 400 / 500 / 550 rad/s (0.5 %)', () => {
    for (const entry of cases('VC-DRV-25').filter((c) => c.quantity.startsWith('PMSM envelope torque'))) {
      const speed = Number(/at ([\d.]+) rad/.exec(entry.quantity)?.[1]);
      within(torque(speed), entry);
    }
  });
});

describe('VC-DRV-26: induction (Kloss and the 230 V / 50 Hz equivalent circuit)', () => {
  const motor: InductionMotor = {
    id: 'm',
    kind: 'induction',
    joint: 'j',
    datasheet: INDUCTION_SHEET,
    source: MACHINE_SOURCE as InductionMotor['source'],
  };
  const p = inductionParameters(motor);
  const sync = synchronousSpeed(p, 50);
  const torqueAtSlip = (slip: number): number => inductionPoint(p, 230, 50, sync * (1 - slip)).torqueNm;

  /** The slip of the maximum torque by golden-section search over (0.01, 1). */
  const breakdownSlip = (): number => {
    const phi = (Math.sqrt(5) - 1) / 2;
    let [a, b] = [0.01, 1];
    for (let k = 0; k < 120; k++) {
      const [c, d] = [b - phi * (b - a), a + phi * (b - a)];
      if (torqueAtSlip(c) > torqueAtSlip(d)) b = d;
      else a = c;
    }
    return (a + b) / 2;
  };

  it('breakdown torque, breakdown slip and starting torque of the circuit (1e-6): numerical maximum and the slip-1 point', () => {
    within(torqueAtSlip(breakdownSlip()), caseOf('VC-DRV-26', 'breakdown torque of the equivalent circuit'));
    within(breakdownSlip(), caseOf('VC-DRV-26', 'breakdown slip of the equivalent circuit'));
    within(torqueAtSlip(1), caseOf('VC-DRV-26', 'starting torque of the equivalent circuit'));
  });

  it('Kloss torque at slip 0.05 / 0.1 / 0.5 / 1 for T_b 100, s_b 0.1 (1e-9): the circuit with R1 = 0, R2 = 0.2 ohm, X = 2 ohm at the voltage that gives T_b = 100', () => {
    const kloss = inductionParameters({ ...motor, datasheet: { ...INDUCTION_SHEET, statorResistanceOhm: 1e-12, rotorResistanceOhm: 0.2 } });
    const volts = Math.sqrt((100 * 2 * sync * 2) / 3);
    for (const entry of cases('VC-DRV-26').filter((c) => c.quantity.startsWith('Kloss'))) {
      const slip = Number(/slip ([\d.]+)/.exec(entry.quantity)?.[1]);
      within(inductionPoint(kloss, volts, 50, sync * (1 - slip)).torqueNm, entry);
    }
  });
});

describe('VC-DRV-27: stepper (T_h 0.5 N m, N_r 50, J 1e-5) measured through the engine', () => {
  it('small-angle natural frequency from a ringing run (2 %)', () => {
    const doc = machineBench(1e-9, { kind: 'stepper', stepperDatasheet: STEPPER_SHEET }, [
      {
        command: 'add_motion_profile',
        params: { id: 'p', quantity: 'position', unit: 'deg', segments: [{ kind: 'move', law: 'linear', to: 0.0844, duration: 1e-4 }] },
      },
      { command: 'set_motor_drive', params: { motor: 'm', mode: 'position', profile: 'p', stepDivision: 64 } },
    ]);
    const result = simulate(doc, { duration: 0.03, sampleRate: 100000, timestep: 1e-5, detail: 'drives' });
    const times = (result.data as { series: { times: number[] } }).series.times;
    const x = seriesOf(result, 'jointPosition', 'j');
    const target = (3 * (2 * Math.PI)) / 200 / 64;
    const crossings: number[] = [];
    for (let k = 1; k < x.length; k++) {
      const [a, b, t0, t1] = [(x[k - 1] ?? 0) - target, (x[k] ?? 0) - target, times[k - 1] ?? 0, times[k] ?? 0];
      if (t1 > 0.001 && a < 0 && b >= 0) crossings.push(t0 + (t1 - t0) * (-a / (b - a)));
    }
    const period = ((crossings[crossings.length - 1] ?? 0) - (crossings[0] ?? 0)) / (crossings.length - 1);
    within(1 / period, caseOf('VC-DRV-27', 'natural frequency'));
  });

  it('static deflection at half the holding torque, from a loaded run with a damped rotor (1 %)', () => {
    const doc = machineBench(1e-5, { kind: 'stepper', stepperDatasheet: { ...STEPPER_SHEET, dampingNmsPerRad: 0.02 } }, [
      {
        command: 'add_motor',
        params: { joint: 'j', id: 'load_torque', kind: 'torque_curve', torque: -0.25, source: { name: 'test load', grade: 'A' } },
      },
      { command: 'add_motion_profile', params: { id: 'p', quantity: 'position', unit: 'deg', segments: [{ kind: 'dwell', duration: 1 }] } },
      { command: 'set_motor_drive', params: { motor: 'm', mode: 'position', profile: 'p' } },
    ]);
    const result = simulate(doc, { duration: 0.2, sampleRate: 10000, timestep: 1e-4, detail: 'drives' });
    const positions = seriesOf(result, 'jointPosition', 'j');
    within((Math.abs(positions[positions.length - 1] ?? Number.NaN) * 180) / Math.PI, caseOf('VC-DRV-27', 'static deflection'));
  });
});
